//! Languages of the user interface.
//!
//! Klaub has no translation files to parse at run time. Every sentence the reader or the command
//! line shows is a function in [`tui`] or [`cli`], generated by `messages!` / `texts!` below. A
//! function takes the [`Locale`] first and then the values the sentence mentions, so:
//!
//! - a language missing from an entry is a **compile error**, not a blank at run time;
//! - a placeholder that is misspelt or not provided is a compile error too, because the text is a
//!   `format!` string;
//! - each sentence is written next to its translations, which keeps them reviewable together.
//!
//! This module is pure. Reading the environment is the job of the composition root, which hands
//! [`Locale::detect`] a lookup function.

/// Defines functions that build a sentence from values, one text per language.
///
/// ```ignore
/// messages! {
///     fn greeting(name: &str) { en: "Hello, {name}" }
/// }
/// ```
macro_rules! messages {
    ($(
        $(#[$meta:meta])*
        fn $name:ident($($arg:ident: $ty:ty),* $(,)?) {
            en: $en:literal $(,)?
        }
    )*) => {$(
        $(#[$meta])*
        #[must_use]
        pub fn $name(locale: $crate::domain::i18n::Locale, $($arg: $ty),*) -> String {
            match locale {
                $crate::domain::i18n::Locale::En => format!($en),
            }
        }
    )*};
}

/// Defines constants-like functions for sentences without values, one text per language.
macro_rules! texts {
    ($(
        $(#[$meta:meta])*
        const $name:ident {
            en: $en:literal $(,)?
        }
    )*) => {$(
        $(#[$meta])*
        #[must_use]
        pub const fn $name(locale: $crate::domain::i18n::Locale) -> &'static str {
            match locale {
                $crate::domain::i18n::Locale::En => $en,
            }
        }
    )*};
}

pub mod cli;
pub mod tui;

/// A language Klaub can speak.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash)]
pub enum Locale {
    /// English, the language the program is written in and the fallback for every other one.
    #[default]
    En,
}

impl Locale {
    /// Every language, in the order they are listed to the user.
    pub const ALL: [Self; 1] = [Self::En];

    /// The two-letter code used in `ui.language` and `KLAUB_LANG`.
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::En => "en",
        }
    }

    /// The language a locale tag such as `en`, `en_US.UTF-8` or `en-GB` asks for.
    ///
    /// Only the language part counts. `None` for a tag Klaub has no translation for, including
    /// `C` and `POSIX`.
    #[must_use]
    pub fn from_tag(tag: &str) -> Option<Self> {
        let language = tag
            .trim()
            .split(['_', '-', '.', '@'])
            .next()
            .unwrap_or_default()
            .to_ascii_lowercase();
        Self::ALL
            .into_iter()
            .find(|locale| locale.code() == language)
    }

    /// The language the environment asks for, if it is one Klaub speaks.
    ///
    /// `KLAUB_LANG` comes first, then the POSIX variables in their order of precedence
    /// (`LC_ALL`, `LC_MESSAGES`, `LANG`). The first one that is set and not empty decides: a user
    /// with `LC_ALL=fr_FR` gets English, not whatever `LANG` says.
    #[must_use]
    pub fn detect(get: &dyn Fn(&str) -> Option<String>) -> Option<Self> {
        ["KLAUB_LANG", "LC_ALL", "LC_MESSAGES", "LANG"]
            .into_iter()
            .find_map(|key| get(key).filter(|value| !value.trim().is_empty()))
            .and_then(|value| Self::from_tag(&value))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn env(pairs: &[(&str, &str)]) -> impl Fn(&str) -> Option<String> {
        let map: HashMap<String, String> = pairs
            .iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect();
        move |key| map.get(key).cloned()
    }

    #[test]
    fn tags_are_matched_on_their_language_part() {
        for tag in ["en", "EN", "en_US.UTF-8", "en-GB", " en_US@euro "] {
            assert_eq!(Locale::from_tag(tag), Some(Locale::En), "{tag}");
        }
        for tag in ["", "C", "POSIX", "xx_XX", "eng"] {
            assert_eq!(Locale::from_tag(tag), None, "{tag}");
        }
    }

    #[test]
    fn the_first_variable_that_is_set_decides() {
        assert_eq!(Locale::detect(&env(&[])), None);
        assert_eq!(
            Locale::detect(&env(&[("LANG", "en_US.UTF-8")])),
            Some(Locale::En)
        );
        // `LC_ALL` wins over `LANG`, even when it names a language Klaub does not speak.
        assert_eq!(
            Locale::detect(&env(&[("LC_ALL", "fr_FR"), ("LANG", "en_US")])),
            None
        );
        // An empty variable counts as unset.
        assert_eq!(
            Locale::detect(&env(&[("LC_ALL", ""), ("LANG", "en_US")])),
            Some(Locale::En)
        );
        assert_eq!(
            Locale::detect(&env(&[("KLAUB_LANG", "en"), ("LC_ALL", "fr_FR")])),
            Some(Locale::En)
        );
    }

    #[test]
    fn every_language_has_a_distinct_code_that_parses_back() {
        for locale in Locale::ALL {
            assert_eq!(Locale::from_tag(locale.code()), Some(locale));
        }
    }
}
